Web Frontend.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Frontend container

Container_Boundary(web_frontend, "Web Frontend") {
    Component(Core_UI_Framework, "Core UI Framework", "React / HTML / JavaScript (Storybook, Custom Hooks)", "Core UI framework providing component-driven development and data-fetching abstraction.")
    Component(Runtime_Reverse_Proxy, "Runtime Reverse-Proxy", "NGINX", "Hosts local static assets, polyfills, and fonts with enforced Content Security Policies.")
    Component(Testing_and_Compliance_Suite, "Testing and Compliance Suite", "Jest, React Testing Library, Playwright, Cypress, axe-core", "Handles unit, integration, E2E smoke testing, and automated accessibility (a11y) testing for WCAG compliance.")
}

Rel(Core_UI_Framework, Runtime_Reverse_Proxy, "Serves static assets and routes traffic through")

@enduml

User Portals.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(user_portals, "User Portals") {
    Component(RepositoryLayer, "Repository Layer", "Spring Boot", "Implements data persistence and retrieval patterns for EU-hosted data.")
    Component(ServiceLayer, "Service Layer", "Spring Boot", "Contains core business logic, orchestrating calls to cache, database, and message broker.")
    Component(ExceptionHandler, "Exception Handler", "RFC 7807", "Provides standardized Problem Details for global exception handling and error mapping.")
    Component(HealthProbe, "Health Probe", "Spring Boot Actuator", "Provides liveness, readiness, and startup probes for OCI container orchestration.")
}

Rel(ServiceLayer, RepositoryLayer, "Queries and updates data")
Rel(ServiceLayer, ExceptionHandler, "Maps errors to RFC 7807 problem details")

@enduml

Elasticsearch / OpenSearch Search Contai.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Elasticsearch / OpenSearch Search Container container

Container_Boundary(elasticsearch_opensearch_search_container, "Elasticsearch / OpenSearch Search Container") {
    Component(Search_Query_Engine, "Search Query Engine", "Elasticsearch / OpenSearch", "Executes high-performance search queries meeting sub-800ms P99 performance requirements.")
    Component(Index_Management_Module, "Index Management Module", "Index Aliases / ILM", "Handles blue-green zero-downtime reindexing and automated tiering for EU-hosted persistence volumes.")
}

Rel(Search_Query_Engine, Index_Management_Module, "Uses for index lifecycle and zero-downtime alias management", "Internal")

@enduml

Isolated Microservice Databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(isolated_microservice_databases, "Isolated Microservice Databases") {
    Component(Catalog_Management_Database, "Catalog Management Database", "Relational/NoSQL Database", "Stores catalog and bibliographic data with strict EU-only data residency.")
    Component(Circulation_Database, "Circulation Database", "Relational/NoSQL Database", "Stores circulation, checkout, and patron transaction records.")
    Component(User_Portals_Database, "User Portals Database", "Relational/NoSQL Database", "Stores user profiles, preferences, and portal session data.")
}

Rel(Catalog_Management_Database, Circulation_Database, "Synchronizes bibliographic state")

@enduml

Centralized Configuration Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(CentralizedConfigurationStore, "Centralized Configuration Store") {
    Component(ConfigurationServer, "Configuration Server", "Spring Cloud Config", "Serves immutable configurations to client containers and maintains centralized configuration state.")
    Component(KeyValueStoreBackend, "Key-Value Store Backend", "Consul", "Provides the underlying data store for configuration management and supports immutable image builds and data residency requirements.")
}

Rel(ConfigurationServer, KeyValueStoreBackend, "Fetches and persists configuration data", "TCP")

@enduml

Log/Metrics Collector Agent.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Log/Metrics Collector Agent container

Container_Boundary(log_metrics_collector_agent_boundary, "Log/Metrics Collector Agent") {
    Component(Log/Metrics_Collector_Agent, "Log/Metrics Collector Agent", "OTel Collector / Fluentd", "Collects logs and metrics, executes PII sanitization at the source, and provides local disk-backed buffering.")
}

System_Ext(Monitoring_and_Telemetry_Aggregator, "Monitoring and Telemetry Aggregator", "Aggregates telemetry data.")
System_Ext(Centralized_Configuration_Store, "Centralized Configuration Store", "Stores externalized parsing and sanitization rules.")

Rel(Log/Metrics_Collector_Agent, Monitoring_and_Telemetry_Aggregator, "Forwards structured JSON logs and metrics via TLS", "TLS")
Rel(Log/Metrics_Collector_Agent, Centralized_Configuration_Store, "Fetches externalized parsing and sanitization rules via API/RPC", "API/RPC")

@enduml
